[ExtensionOf(classStr(MarkupTransInsert))]
internal final class METMarkupTransInsert_Extension
{
    private boolean metCalledFromPriceSimulator;

}

Method.Source:
/// <summary>
/// Get/set metCalledFromPriceSimulator
/// </summary>
/// <param name = "_metCalledFromPriceSimulator"_metCalledFromPriceSimulator></param>
/// <returns>metCalledFromPriceSimulator</returns>
public boolean metParmCalledFromPriceSimulator(boolean _metCalledFromPriceSimulator = metCalledFromPriceSimulator)
{
    metCalledFromPriceSimulator = _metCalledFromPriceSimulator;
    return metCalledFromPriceSimulator;
}

/// <summary>
/// CoC
/// </summary>
/// <returns></returns>
protected boolean shouldSkipOriginalInsertMatchingCharges()
{
    boolean ret = next shouldSkipOriginalInsertMatchingCharges();
    if(this.metParmCalledFromPriceSimulator())
    {
        ret = false;
    }
    return ret;
}

    /// <summary>
    /// CoC
    /// </summary>
    /// <param name = "_searchParameter">_searchParameter</param>
    /// <returns>MarkupAutoTable</returns>
    protected MarkupAutoTable findMarkupAutoTableByNaturalKey(MarkupAutoTable _searchParameter)
    {
        MarkupAutoTable  markupAutoTable = next findMarkupAutoTableByNaturalKey(_searchParameter);

        if(this.metParmCalledFromPriceSimulator())
        {
            select firstonly markupAutoTable
                index hint MarkupIdx
                where markupAutoTable.ModuleCategory        == _searchParameter.ModuleCategory        &&
                      markupAutoTable.ModuleType            == _searchParameter.ModuleType            &&
                      markupAutoTable.AccountCode           == _searchParameter.AccountCode           &&
                      markupAutoTable.AccountRelation       == _searchParameter.AccountRelation       &&
                      markupAutoTable.ItemCode              == _searchParameter.ItemCode              &&
                      markupAutoTable.ItemRelation          == _searchParameter.ItemRelation          &&
                      markupAutoTable.MarkupReturn          == _searchParameter.MarkupReturn          &&
                      markupAutoTable.DlvModeCode           == _searchParameter.DlvModeCode           &&
                      markupAutoTable.DlvModeRelation       == _searchParameter.DlvModeRelation       &&
                      markupAutoTable.ReturnRelation        == _searchParameter.ReturnRelation;               
        }

        return markupAutoTable;
    }
